SELECT 'gongkao', '比例倍数问题', 'kp-xc-quantity-math-operation-ratio-multiple', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "比例倍数问题"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心结论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "比例倍数问题是数量关系的基础工具，正反比关系广泛应用于行程、工程、浓度等多个模块。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、知识要点"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "正比关系：y = kx，x增大y也增大，如速度一定时路程与时间成正比"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "反比关系：y = k/x，x增大y减小，如路程一定时速度与时间成反比"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "连比与份数：a:b:c = m:n:p，总份数为m+n+p，各部分占比为m/(m+n+p)"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "按比例分配：总量按份数比分配，每份 = 总量/总份数"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "比例变化：原始比a:b，变化后a':b'，用比例统一法求解"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、解题方法"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "正反比判断：固定一个量，看另外两个量的关系"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "份数法：把比例看成份数，用份数的增减来分析变化"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "比例统一：多个比例中找公共量，统一份数后合并"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "代入验证：用比例关系代入原题验证是否正确"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "正反比判断错误：把正比当成反比或 vice versa"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "连比没有统一公共量，直接把两个比例的数字拼在一起"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "比例变化时忘记考虑基数的变化"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "比例倍数是很多题型的基础工具，必须熟练。建议先掌握正反比和份数法，再练习综合应用。"}]}]}]}$$ AS jsonb), NULL, '数量关系-数学运算-比例倍数问题的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "数学运算", "比例倍数问题"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_quantity_math_operation_ratio_multiple", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
